"use client";

import { useId, useState } from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import type { Transition } from "motion/react";
import { BookOpen, Brain, Check, ChevronDown, PenLine, Search, Terminal, X } from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { motionTokens } from "@/lib/motion-tokens";
import styles from "./agent-activity.module.css";

export type AgentStepKind = "search" | "read" | "write" | "think" | "run";
export type AgentStepStatus = "pending" | "running" | "done" | "error";

export interface AgentStep {
  /** Stable id of the step. */
  id: string;
  /** What kind of work the step is; it picks the icon. */
  kind: AgentStepKind;
  /** What the agent is doing, in a few words: "Searching the codebase". */
  title: string;
  /** One line of detail: the query, the file, the command. */
  detail?: string;
  /** Short things the step found or touched (file names, sites, results). They appear as chips, one by one as the list grows. */
  items?: string[];
  /** Where the step is. */
  status: AgentStepStatus;
  /** How long the step took, in milliseconds. Shown once it has finished. */
  duration?: number;
}

export interface AgentActivityProps {
  /** The steps in order. Update their status as the agent works. */
  steps: AgentStep[];
  /** Heading of the timeline: usually the task the agent was given. */
  title?: string;
  /** Whether the finished steps are shown in full (controlled). */
  expanded?: boolean;
  /** Whether the finished steps start shown in full (uncontrolled). By default they fold into one summary row. */
  defaultExpanded?: boolean;
  /** Called when the summary row opens or closes the finished steps. */
  onExpandedChange?: (expanded: boolean) => void;
  /** Class name added to the root element. */
  className?: string;
}

const icons: Record<AgentStepKind, LucideIcon> = { search: Search, read: BookOpen, write: PenLine, think: Brain, run: Terminal };
const standard = [...motionTokens.ease.standard] as [number, number, number, number];

function formatDuration(ms: number) {
  const seconds = ms / 1000;
  if (seconds < 10) return `${seconds.toFixed(1)}s`;
  if (seconds < 60) return `${Math.round(seconds)}s`;
  return `${Math.floor(seconds / 60)}m ${Math.round(seconds % 60)}s`;
}

function StepRow({ step, line, reduceMotion }: { step: AgentStep; line: boolean; reduceMotion: boolean }) {
  const Icon = step.status === "done" ? Check : step.status === "error" ? X : icons[step.kind];
  return (
    <div className={styles.step} data-status={step.status}>
      <span className={styles.rail} aria-hidden="true">
        <span className={styles.node}><Icon size={13} strokeWidth={step.status === "done" || step.status === "error" ? 2.75 : 2} /></span>
        {line ? <span className={styles.line} /> : null}
      </span>
      <div className={styles.body}>
        <div className={styles.titleRow}>
          <span className={styles.title}>{step.title}</span>
          {step.status === "pending" ? <span className={styles.srOnly}> (waiting)</span> : null}
          {step.status === "error" ? <span className={styles.srOnly}> (failed)</span> : null}
          {step.duration != null && (step.status === "done" || step.status === "error") ? <span className={styles.duration}>{formatDuration(step.duration)}</span> : null}
        </div>
        {step.detail ? <p className={styles.detail}>{step.detail}</p> : null}
        {step.items?.length ? (
          <ul className={styles.chips}>
            <AnimatePresence initial={false}>
              {step.items.map(item => (
                <motion.li key={item} className={styles.chip} initial={reduceMotion ? false : { opacity: 0, scale: 0.8, y: 4 }} animate={{ opacity: 1, scale: 1, y: 0 }} transition={motionTokens.spring.snappy}>{item}</motion.li>
              ))}
            </AnimatePresence>
          </ul>
        ) : null}
      </div>
    </div>
  );
}

/**
 * A live timeline of what an agent is doing. The step in progress pulses and collects what it finds as chips; a step that finishes
 * leaves the live list and folds into one summary row that counts steps and time, which opens to show them again.
 */
export function AgentActivity({ steps, title = "Agent activity", expanded, defaultExpanded = false, onExpandedChange, className }: AgentActivityProps) {
  const reduceMotion = useReducedMotion() ?? false;
  const regionId = useId();
  const [internal, setInternal] = useState(defaultExpanded);
  const isExpanded = expanded ?? internal;
  const finished = steps.filter(step => step.status === "done" || step.status === "error");
  const live = steps.filter(step => step.status === "running" || step.status === "pending");
  const running = steps.find(step => step.status === "running");
  const failed = finished.filter(step => step.status === "error").length;
  const allDone = steps.length > 0 && live.length === 0;
  const elapsed = finished.reduce((sum, step) => sum + (step.duration ?? 0), 0);
  const fold: Transition = reduceMotion ? { duration: 0 } : motionTokens.spring.smooth;
  const toggle = () => { const next = !isExpanded; if (expanded === undefined) setInternal(next); onExpandedChange?.(next); };

  return (
    <section className={[styles.root, className].filter(Boolean).join(" ")} aria-label={title} data-state={allDone ? "done" : running ? "running" : "idle"}>
      <header className={styles.header}>
        <span className={styles.state} aria-hidden="true">
          <AnimatePresence initial={false} mode="popLayout">
            {allDone ? (
              <motion.span key="done" className={styles.stateDone} initial={reduceMotion ? false : { scale: 0.4, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} transition={motionTokens.spring.snappy}><Check size={12} strokeWidth={3} /></motion.span>
            ) : (
              <motion.span key="spin" className={styles.spinner} data-active={Boolean(running)} exit={{ scale: 0.4, opacity: 0 }} transition={{ duration: motionTokens.duration.instant }} />
            )}
          </AnimatePresence>
        </span>
        <h3 className={styles.heading}>{title}</h3>
        <span className={styles.tally} aria-label={`${finished.length} of ${steps.length} steps finished`}>
          {allDone ? "Done" : <><span className={styles.tallyNow}>{finished.length}</span> / {steps.length}</>}
        </span>
      </header>

      <div className={styles.timeline}>
        <AnimatePresence initial={false}>
          {finished.length > 0 ? (
            <motion.div key="summary" className={styles.fold} initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={fold}>
              <div className={styles.step} data-status="summary">
                <span className={styles.rail} aria-hidden="true">
                  <span className={styles.node}><Check size={13} strokeWidth={2.75} /></span>
                  {live.length > 0 || isExpanded ? <span className={styles.line} /> : null}
                </span>
                <button type="button" className={styles.summary} onClick={toggle} aria-expanded={isExpanded} aria-controls={regionId}>
                  <span className={styles.summaryText}>
                    <span className={styles.roll}>
                      <AnimatePresence initial={false} mode="popLayout">
                        <motion.span key={finished.length} className={styles.rollDigit} initial={reduceMotion ? false : { y: "0.7em", opacity: 0 }} animate={{ y: 0, opacity: 1 }} exit={reduceMotion ? { opacity: 0, transition: { duration: 0 } } : { y: "-0.7em", opacity: 0, transition: { duration: motionTokens.duration.fast, ease: standard } }} transition={motionTokens.spring.snappy}>{finished.length}</motion.span>
                      </AnimatePresence>
                    </span>
                    {finished.length === 1 ? " step finished" : " steps finished"}
                    {failed ? <span className={styles.failedCount}>{failed} failed</span> : null}
                  </span>
                  {elapsed > 0 ? <span className={styles.duration}>{formatDuration(elapsed)}</span> : null}
                  <ChevronDown className={styles.chevron} size={15} aria-hidden="true" />
                </button>
              </div>
            </motion.div>
          ) : null}
        </AnimatePresence>

        <motion.div id={regionId} className={styles.fold} initial={false} animate={{ height: isExpanded && finished.length ? "auto" : 0, opacity: isExpanded ? 1 : 0 }} transition={fold} inert={!isExpanded}>
          <ol className={styles.list} aria-label="Finished steps">
            <AnimatePresence initial={false}>
              {finished.map((step, index) => (
                <motion.li key={step.id} className={styles.fold} initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={fold}>
                  <StepRow step={step} line={index < finished.length - 1 || live.length > 0} reduceMotion={reduceMotion} />
                </motion.li>
              ))}
            </AnimatePresence>
          </ol>
        </motion.div>

        <ol className={styles.list} aria-label="Steps in progress">
          <AnimatePresence initial={false}>
            {live.map((step, index) => (
              <motion.li key={step.id} className={styles.fold} initial={{ height: 0, opacity: 0 }} animate={{ height: "auto", opacity: 1 }} exit={{ height: 0, opacity: 0 }} transition={fold}>
                <StepRow step={step} line={index < live.length - 1} reduceMotion={reduceMotion} />
              </motion.li>
            ))}
          </AnimatePresence>
        </ol>
      </div>
      <span className={styles.srOnly} role="status">{allDone ? `Finished ${steps.length} steps` : running ? running.title : ""}</span>
    </section>
  );
}

export default AgentActivity;

.root { position: relative; width: 100%; min-width: 0; padding: var(--space-4) var(--space-3) var(--space-2); border: 1px solid var(--border); border-radius: var(--radius-panel); background: var(--surface); color: var(--foreground); box-shadow: var(--shadow-resting); font-family: var(--font-body); font-size: var(--text-sm); letter-spacing: var(--tracking-body); line-height: var(--leading-body); }

.header { display: flex; min-width: 0; align-items: center; gap: var(--space-3); padding: 0 var(--space-2) var(--space-3); }
.state { position: relative; display: grid; width: 28px; height: 20px; flex: none; place-items: center; }
.spinner { width: 16px; height: 16px; border: 2px solid var(--border-strong); border-radius: var(--radius-pill); }
.spinner[data-active="true"] { border-color: color-mix(in oklab, var(--accent-strong) 28%, transparent); border-top-color: var(--accent-strong); animation: spin .8s linear infinite; }
.stateDone { display: grid; width: 20px; height: 20px; place-items: center; border-radius: var(--radius-pill); background: var(--accent); color: var(--accent-foreground); }
.heading { min-width: 0; flex: 1; margin: 0; overflow: hidden; font-family: var(--font-display); font-size: var(--text-base); font-weight: 600; letter-spacing: var(--tracking-display); line-height: 1.3; text-overflow: ellipsis; white-space: nowrap; }
.tally { flex: none; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; font-weight: 500; }
.tallyNow { color: var(--foreground); }

.timeline { min-width: 0; }
.list { margin: 0; padding: 0; list-style: none; }
/* Rows open and close by height. The side padding keeps the pulse of the running node inside the clipped box. */
.fold { overflow: clip; }

.step { display: grid; grid-template-columns: 28px minmax(0, 1fr); column-gap: var(--space-3); padding: 2px var(--space-2) 0; }
.rail { display: flex; flex-direction: column; align-items: center; }
.node { position: relative; display: grid; width: 24px; height: 24px; flex: none; place-items: center; border-radius: var(--radius-pill); background: var(--surface-muted); color: var(--text-secondary); transition: background-color var(--duration-standard) var(--ease-standard), color var(--duration-standard) var(--ease-standard), box-shadow var(--duration-standard) var(--ease-standard); }
.line { width: 2px; min-height: var(--space-3); flex: 1; margin: 3px 0 1px; border-radius: var(--radius-pill); background: var(--border); }
.body { min-width: 0; padding: 2px 0 var(--space-4); }
.titleRow { display: flex; min-width: 0; align-items: baseline; gap: var(--space-2); }
.title { min-width: 0; font-weight: 500; overflow-wrap: anywhere; }
.duration { flex: none; margin-left: auto; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.detail { margin: 2px 0 0; overflow: hidden; color: var(--text-secondary); font-family: var(--font-mono, ui-monospace, "SF Mono", Menlo, monospace); font-size: var(--text-xs); line-height: 1.5; text-overflow: ellipsis; white-space: nowrap; }
.chips { display: flex; flex-wrap: wrap; gap: var(--space-1); margin: var(--space-2) 0 0; padding: 0; list-style: none; }
.chip { max-width: 100%; overflow: hidden; padding: 2px var(--space-2); border: 1px solid var(--border); border-radius: var(--radius-pill); background: var(--surface); color: var(--text-secondary); font-size: var(--text-xs); line-height: 1.5; text-overflow: ellipsis; white-space: nowrap; }

/* Waiting: hollow and quiet. */
.step[data-status="pending"] .node { background: transparent; color: var(--text-muted); box-shadow: inset 0 0 0 1.5px var(--border-strong); }
.step[data-status="pending"] .title { color: var(--text-muted); }
.step[data-status="pending"] .detail { opacity: .7; }
/* In progress: the node takes the accent and a ring pulses out of it; the title carries a moving sheen (a shimmer, the one gradient here). */
.step[data-status="running"] .node { background: var(--accent); color: var(--accent-foreground); }
.step[data-status="running"] .node::after { content: ""; position: absolute; inset: 0; border-radius: inherit; box-shadow: 0 0 0 2px var(--accent-strong); opacity: 0; animation: pulse 1.6s var(--ease-standard) infinite; }
.step[data-status="running"] .title { background: linear-gradient(100deg, var(--foreground) 35%, var(--text-muted) 50%, var(--foreground) 65%) 0 0 / 220% 100%; -webkit-background-clip: text; background-clip: text; color: transparent; animation: sheen 1.8s linear infinite; }
.step[data-status="done"] .node, .step[data-status="summary"] .node { background: var(--accent-subtle); color: var(--accent-strong); }
.step[data-status="done"] .title { color: var(--text-secondary); }
.step[data-status="error"] .node { background: color-mix(in oklab, var(--danger) 16%, transparent); color: var(--danger); }
.step[data-status="error"] .title { color: var(--danger); }

.summary { display: flex; min-width: 0; align-items: center; gap: var(--space-2); margin: -2px calc(var(--space-2) * -1) var(--space-3); padding: 4px var(--space-2); border: 0; border-radius: var(--radius-control); background: transparent; color: var(--foreground); font: inherit; font-weight: 500; text-align: left; cursor: pointer; -webkit-tap-highlight-color: transparent; --focus-outline-offset: -2px; transition: background-color var(--duration-fast) var(--ease-standard); }
@media (hover: hover) and (pointer: fine) { .summary:hover { background: var(--surface-muted); } }
.summaryText { min-width: 0; flex: 1; }
.roll { position: relative; display: inline-block; font-variant-numeric: tabular-nums; }
.rollDigit { display: inline-block; }
.failedCount { margin-left: var(--space-2); color: var(--danger); font-size: var(--text-xs); }
.summary .duration { margin-left: 0; }
.chevron { flex: none; color: var(--text-muted); transition: rotate var(--duration-spring) var(--ease-spring); }
.summary[aria-expanded="true"] .chevron { rotate: 180deg; }
.srOnly { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

@keyframes pulse { 0% { opacity: .7; transform: scale(1); } 70%, 100% { opacity: 0; transform: scale(1.55); } }
@keyframes sheen { from { background-position: 100% 0; } to { background-position: -120% 0; } }
@keyframes spin { to { rotate: 360deg; } }
@media (prefers-reduced-motion: reduce) {
  .step[data-status="running"] .node::after, .spinner[data-active="true"] { animation: none; }
  .step[data-status="running"] .title { animation: none; background: none; color: var(--foreground); }
  .node, .chevron, .summary { transition: none; }
}
